import type { RangeItem } from '../types/range-legend.js';

//In order to know if a diverging legend should be used we verify if within the items provided
// one of them has equal 'from' and 'to' values. This was established in the API agreement to mean it is a diverging point.
export const getDivergentPointIndex = (items: RangeItem[]) => {
  return items.findIndex((item) => item.from === item.to);
};
